-- Автообновления
function update()
    local raw = "https://raw.githubusercontent.com/bogfix/autorep/main/version.json"
    local dlstatus = require('moonloader').download_status
    local requests = require('requests')
    local f = {}
    function f:getLastVersion()
        local response = requests.get(raw)
        if response.status_code == 200 then
            return decodeJson(response.text)['last']
        else
            return 'UNKNOWN'
        end
    end
    function f:download()
        local response = requests.get(raw)
        if response.status_code == 200 then
            downloadUrlToFile(decodeJson(response.text)['url'], thisScript().path, function (id, status, p1, p2)
                print('Скачиваю '..decodeJson(response.text)['url']..' в '..thisScript().path)
                if status == dlstatus.STATUSEX_ENDDOWNLOAD then
                    sms('Скрипт обновлен, перезагрузка...', 'INFO')
                    sms('После обновления не забудьте перезагрузить все скрипты через CTRL + R', 'WARNING')
                    thisScript():reload()
                end
            end)
        else
            sms('Ошибка, невозможно установить обновление, код: '..response.status_code, 'ERROR')
        end
    end
    return f
end

