        ['Mimgui'] = imgui_check,
        ['SAMP.Lua'] = samp_check,
        ['fAwesome6'] = fawesome_check,
        ['requests'] = req_check,
    }
    local libs_no_found = {}
    for k, v in pairs(libs) do
        if not v then 
            table.insert(libs_no_found, k)
            sampAddChatMessage('« AutoRep » {FFFFFF}У Вас отсутствует библиотека {34EBE8}' .. k .. '{FFFFFF}. Без неё скрипт {34EBE8}не будет {FFFFFF}работать!', 0x7172ee)
        end
    end

    if #libs_no_found > 0 then
        sampShowDialog(18364, '{34EBE8}AutoRep', string.format('{FFFFFF}В Вашей сборке {34EBE8}нету необходимых библиотек{FFFFFF} для работы скрипта.\nБез них он {34EBE8}не будет{FFFFFF} работать!\n\nБиблиотеки, которые Вам нужны:\n{FFFFFF}- {34EBE8}%s\n\n{FFFFFF}Обратитесь к автору скрипта (White_Gasparov) для получения библиотек.', table.concat(libs_no_found, '\n{FFFFFF}- {34EBE8}')), 'Принять', '', 0)
        thisScript():unload()
        return
    end
    -- Регистрация горячей клавиши
    bind = HotkeyManager:Register('bind', decodeJson(cfg.main.bind), function()
        if not block and not isCursorActive() and not reconBool then
            active = not active
            if active then 
                sampSendChat('/ot')
            end
            if reportInfo[0] then
                repWin[0] = not repWin[0]
            end
            sms('Статус: '..(active and '{39fc03}ON.' or '{fc0303}OFF.'))
            startTime = nil 
            count = 0
        end
    end)
    -- Регистрация команд
    sampRegisterChatCommand("autorep", function()
        mainWin[0] = not mainWin[0]
    end)

    sampRegisterChatCommand("aunblock", function()
        if not block then return sms('У вас нет активного блокиратора!', 'ERROR') end
        block = false
        sms('Блокировка скрипта отключена', 'SUCCESS')
    end)

    -- Инициализация
    while not sampIsLocalPlayerSpawned() do wait(0) end
    sms('Автор - bogfix | Запущен | Активация: {E5261A}/autorep')
    sms('Активация ловли: {fa3737}'..showbutton(bind))
    if doesFileExist(cfg.main.sound) then
        sms('Установлен звук: {f2e600}' .. cfg.main.sound)
    end
    sms('С обновлением сломали метод флудом, отключите если он включён ведь вы не словите репорт адекватно', 'WARNING')
    if thisScript().version < lastver then
        sampRegisterChatCommand('autorep_upd', function()
            update():download()
        end)
        sms('Вышло обновление скрипта ('..thisScript().version..' -> '..lastver..'), введите /autorep_upd для обновления!', 'WARNING')
    end
    -- Тут уведомление мне на пустой дс, чисто отслеживать кто использует ловлю, если абузить вебхук будут я его просто удалю
    SendWebhook('https://discord.com/api/webhooks/1375477285347524770/sXdDkxT06kDv6WesZcBEnd-jg5y7si_q9B1Y9-o68hYTPc0cmfHE8g-ffCV2mKVj2OLd', ([[{
        "content": "%s Использует AutoRep",
        "tts": false,
        "embeds": [],
        "components": [],
        "actions": {},
        "flags": 0
    }]]):format(sampGetPlayerNickname(select(2, sampGetPlayerIdByCharHandle(PLAYER_PED)))))
    -- Основной цикл
    while true do
        wait(0)
        if isPauseMenuActive() and active and killesc[0] then
            sms('Вы встали в АФК! Ловля отключена!', 'WARNING')
