-- SAMP события
function sampev.onServerMessage(clr, text)
    text = select(1, text:gsub('{%x+}', ''))
    local player, id, report, warning = text:match('%[%W+%] от (.-)%[(%d+)]:(.+) Уже (%d+) жалоб!!!')

    if active and report then
        local hex = intToHex(join_rgb(bgcolor[0] * 255, bgcolor[1] * 255, bgcolor[2] * 255))
        local hexColor = tonumber('0x' .. hex)
        
        sampAddChatMessage('[Репорт] от '.. player ..'['.. id ..']:{FFFFFF}'.. report ..' {E5261A}['..warning..']', hexColor)
        sampSendChat('/ot')
        return false
    end
    
    if text:find('Сейчас нет вопросов в репорт!') and repWin[0] then
        count = count + 1
        return false
    end
    if text:find('Не флуди!') and repWin[0] then
        return false
    end
    if text:find('У Вас нет доступа') and active then
        block = true
        active = false
        repWin[0] = false
        sms('Скрипт посчитал что вы не администратор, если это не так введите /aunblock', 'WARNING')
    end
end
function sampev.onTogglePlayerSpectating(state)
    if not recon[0] then return end
    reconBool = state
end
function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
    if dialogId == 1334 and active then
        active = false
        repWin[0] = false
        sms('Статус: {fc0303}OFF. {FFFFFF}Был пойман репорт!')

        if winmsg[0] then 
            showWindowsNotification(WindowsNotificationIcon.Warning, 'AutoRep', 'Вы словили репорт! Свернитесь в игру!')
        end

        if flash[0] then
            local hwnd = ffi.cast('HWND**', 0xC17054)[0][0]
            ffi.C.FlashWindow(hwnd, true)
        end
        if showwin[0] then
            local CurWin = ffi.C.GetActiveWindow()
            ffi.C.ShowWindow(CurWin, 3)
        end
        if cfg.main.sound then
            local sound = loadAudioStream(cfg.main.sound)
            if sound then 
                setAudioStreamVolume(sound, valuesound[0])
                setAudioStreamState(sound, ev.PLAY)
            end
        end
    end
    
    if dialog[0] and active then 
        sms("Активен диалог. Ловля отключена!", 'WARNING')
        active = false
        repWin[0] = false
    end
end

function sms(text, style)

    local hex = intToHex(join_rgb(bgcolor[0] * 255, bgcolor[1] * 255, bgcolor[2] * 255))
    local hexColor = tonumber('0x' .. hex)
    text = tostring(text):gsub('{mc}', '{' .. hexColor .. '}'):gsub('{%-1}', '{FFFFFF}')

    local Colors = {
        ERROR = '{FF0000}[Ошибка] ',
        WARNING = '{FF4500}[Warning] ',
        SUCCESS = '{00FF00}[Успешно] '
    }

    local color = ''
    if style == 'SUCCESS' or style == 'WARNING' or style == 'ERROR' then
        color = Colors[style]
    end

    sampAddChatMessage('« '..thisScript().name..' » '..color..'{FFFFFF}'..text, hexColor)
end

function showbutton(bind_arg)
    local hotkey = bind_arg:Get()
    if not hotkey or #hotkey == 0 then return 'Нет клавиш' end
    local hotkeyText = ''
    for i, key in ipairs(hotkey) do
        hotkeyText = hotkeyText .. vk.id_to_name(key)
        if i < #hotkey then hotkeyText = hotkeyText .. ' + ' end
    end
    return hotkeyText
end

function move()
    lua_thread.create(function()
        repWin[0] = true
        mainWin[0] = false
        local blocker = true
        sampSetCursorMode(4)
        sms('Нажмите {32CD32}SPACE{FFFFFF} что-бы сохранить позицию', 'WARNING')
        
        while blocker do
            local cX, cY = getCursorPos()
            posX, posY = cX, cY
            if isKeyJustPressed(32) then
                sampSetCursorMode(0)
                blocker = false
                cfg.main.posx, cfg.main.posy = posX, posY
                if inicfg.save(cfg, 'autorep.ini') then
                    sms('Позиция успешно сохранена! Координаты: x - '.. posX..' y - '.. posY..'!', 'SUCCESS')
                    repWin[0] = false
                    mainWin[0] = true
                end
            end
            wait(0)
        end
    end)
end

function imgui.Link(label, description)
    local size = imgui.CalcTextSize(label)
    local width = imgui.GetWindowWidth()
    local p2 = imgui.GetCursorPos()
    imgui.SetCursorPos(imgui.ImVec2(width / 2 - size.x / 2, p2.y))
    local result = imgui.InvisibleButton(label, size)
    imgui.SetCursorPos(imgui.ImVec2(width / 2 - size.x / 2, p2.y))
    local p = imgui.GetCursorScreenPos()

    if imgui.IsItemHovered() then
        if description then
            imgui.BeginTooltip()
            imgui.PushTextWrapPos(600)
            imgui.TextUnformatted(description)
            imgui.PopTextWrapPos()
            imgui.EndTooltip()
        end
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.CheckMark], label)
        imgui.GetWindowDrawList():AddLine(imgui.ImVec2(p.x, p.y + size.y), imgui.ImVec2(p.x + size.x, p.y + size.y), imgui.GetColorU32Vec4(imgui.GetStyle().Colors[imgui.Col.CheckMark]))
    else
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.CheckMark], label)
    end
    return result
end

function imgui.TextQuestion(label, description)
    imgui.TextDisabled(label)
    if imgui.IsItemHovered() then
        imgui.BeginTooltip()
        imgui.PushTextWrapPos(600)
        imgui.TextUnformatted(description)
        imgui.PopTextWrapPos()
        imgui.EndTooltip()
    end
end

