function slider(type, label, varArray, key, minVal, maxVal)
    if type == 'INT' then
        if imgui.SliderInt(label, varArray, minVal, maxVal) then
            cfg.design[key] = varArray[0]
            inicfg.save(cfg, 'autorep.ini')
            imgui.Theme()
        end
    elseif type == 'FLOAT' then
        if imgui.SliderFloat(label, varArray, minVal, maxVal) then
            cfg.design[key] = varArray[0]
            inicfg.save(cfg, 'autorep.ini')
            imgui.Theme()
        end
    end
end
function HSVtoRGB(h, s, v)
    local i = math.floor(h * 6)
    local f = h * 6 - i
    local p = v * (1 - s)
    local q = v * (1 - f * s)
    local t = v * (1 - (1 - f) * s)
    i = i % 6

    if i == 0 then return v, t, p
    elseif i == 1 then return q, v, p
    elseif i == 2 then return p, v, t
    elseif i == 3 then return p, q, v
    elseif i == 4 then return t, p, v
    elseif i == 5 then return v, p, q
    end
end

function join_rgb(r, g, b)
    return bit.bor(bit.bor(b, bit.lshift(g, 8)), bit.lshift(r, 16))
end

function intToHex(int)
    return string.sub(bit.tohex(int), 3, 8)
end

function SendWebhook(URL, DATA, callback_ok, callback_error) -- Функция отправки запроса
    local function asyncHttpRequest(method, url, args, resolve, reject)
        local request_thread = effil.thread(function (method, url, args)
           local requests = require 'requests'
           local result, response = pcall(requests.request, method, url, args)
           if result then
              response.json, response.xml = nil, nil
              return true, response
           else
              return false, response
           end
        end)(method, url, args)
        if not resolve then resolve = function() end end
        if not reject then reject = function() end end
        lua_thread.create(function()
            local runner = request_thread
            while true do
                local status, err = runner:status()
                if not err then
                    if status == 'completed' then
                        local result, response = runner:get()
                        if result then
                           resolve(response)
                        else
                           reject(response)
                        end
                        return
                    elseif status == 'canceled' then
                        return reject(status)
                    end
                else
                    return reject(err)
                end
                wait(0)
            end
        end)
    end
    asyncHttpRequest('POST', URL, {headers = {['content-type'] = 'application/json'}, data = u8(DATA)}, callback_ok, callback_error)
end

